.checkbox-container {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 300px;
  height: 300px;
  z-index: 10;
}

/* Скрываем стандартный чекбокс */
.holo-checkbox-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.holo-checkbox {
  position: relative;
  width: 80px;
  height: 80px;
  cursor: pointer;
  transform-style: preserve-3d;
  perspective: 1000px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.holo-box {
  position: relative;
  width: 100%;
  height: 100%;
  border: 2px solid rgba(0, 162, 255, 0.7);
  border-radius: 12px;
  background-color: rgba(0, 24, 55, 0.5);
  box-shadow:
    0 0 10px rgba(0, 162, 255, 0.5),
    inset 0 0 15px rgba(0, 162, 255, 0.3);
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: hidden;
  transition: all 0.3s ease;
  transform-style: preserve-3d;
}

.holo-inner {
  position: absolute;
  width: 30%;
  height: 30%;
  background-color: rgba(0, 162, 255, 0.5);
  border-radius: 4px;
  opacity: 0;
  transform: scale(0) rotate(45deg);
  transition: all 0.3s ease;
  box-shadow: 0 0 15px rgba(0, 162, 255, 0.8);
}

.scan-effect {
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 2px;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(0, 162, 255, 0.8),
    transparent
  );
  animation: scan-off 4s infinite;
  opacity: 0.3;
  transition: all 0.3s ease;
}

@keyframes scan-off {
  0% {
    left: -100%;
    opacity: 0.3;
  }
  100% {
    left: 100%;
    opacity: 0.3;
  }
}

@keyframes scan-on {
  0% {
    left: -100%;
    opacity: 1;
  }
  100% {
    left: 100%;
    opacity: 1;
  }
}

.holo-checkbox-input:checked + .holo-checkbox .holo-box {
  border-color: rgba(0, 255, 136, 0.7);
  box-shadow:
    0 0 10px rgba(0, 255, 136, 0.6),
    inset 0 0 15px rgba(0, 255, 136, 0.4);
}

.holo-checkbox-input:checked + .holo-checkbox .holo-inner {
  background-color: rgba(0, 255, 136, 0.7);
  box-shadow: 0 0 15px rgba(0, 255, 136, 1);
  opacity: 1;
  transform: scale(1) rotate(45deg);
}

.holo-checkbox-input:checked + .holo-checkbox .scan-effect {
  animation: scan-on 2s infinite;
  opacity: 1;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(0, 255, 136, 0.8),
    transparent
  );
}

.holo-glow {
  position: absolute;
  width: 200%;
  height: 200%;
  left: -50%;
  top: -50%;
  background: radial-gradient(
    ellipse at center,
    rgba(0, 162, 255, 0.2) 0%,
    rgba(0, 162, 255, 0.1) 40%,
    rgba(0, 0, 0, 0) 70%
  );
  pointer-events: none;
  filter: blur(10px);
  opacity: 0.5;
  z-index: -1;
  animation: glow-pulse 4s infinite alternate;
  transition: all 0.5s ease;
}

@keyframes glow-pulse {
  0% {
    opacity: 0.3;
    filter: blur(10px) brightness(0.8);
  }
  100% {
    opacity: 0.6;
    filter: blur(15px) brightness(1.2);
  }
}

.holo-checkbox-input:checked + .holo-checkbox .holo-glow {
  background: radial-gradient(
    ellipse at center,
    rgba(0, 255, 136, 0.2) 0%,
    rgba(0, 255, 136, 0.1) 40%,
    rgba(0, 0, 0, 0) 70%
  );
  animation: active-glow-pulse 2s infinite alternate;
}

@keyframes active-glow-pulse {
  0% {
    opacity: 0.4;
    filter: blur(10px) brightness(1);
  }
  100% {
    opacity: 0.8;
    filter: blur(20px) brightness(1.5);
  }
}

.corner-accent {
  position: absolute;
  width: 15px;
  height: 15px;
  border-style: solid;
  border-width: 2px;
  border-color: rgba(0, 162, 255, 0.5);
  transition: all 0.3s ease;
}

.corner-accent:nth-child(1) {
  top: -5px;
  left: -5px;
  border-right: none;
  border-bottom: none;
  border-radius: 5px 0 0 0;
}

.corner-accent:nth-child(2) {
  top: -5px;
  right: -5px;
  border-left: none;
  border-bottom: none;
  border-radius: 0 5px 0 0;
}

.corner-accent:nth-child(3) {
  bottom: -5px;
  left: -5px;
  border-right: none;
  border-top: none;
  border-radius: 0 0 0 5px;
}

.corner-accent:nth-child(4) {
  bottom: -5px;
  right: -5px;
  border-left: none;
  border-top: none;
  border-radius: 0 0 5px 0;
}

.holo-checkbox-input:checked + .holo-checkbox .corner-accent {
  width: 20px;
  height: 20px;
  border-color: rgba(0, 255, 136, 0.7);
}

.status-text {
