  border: 1px solid rgba(255, 255, 255, 0.22);
}

@media (prefers-reduced-motion: reduce) {
  .toggle-label,
  .toggle-switch,
  .toggle-handle,
  .toggle-icon,
  .toggle-text::after,
  .toggle-handle::after {
    transition-duration: 0.01ms !important;
    transition-delay: 0ms !important;
    animation: none !important;
  }
}

@media (forced-colors: active) {
  .toggle-container,
  .toggle-label,
  .toggle-switch,
